$rel isa acted_in (film: $m);
$rel has roles $r;
reduce $numRoles = count($r) groupby $m;
sort $numRoles desc;
limit 5;
fetch {
  "movieTitle": $m.title,
  "numRoles": $numRoles
};

match
$m isa movie;
$rel isa acted_in (actor: $p, film: $m);
$rel has roles $r;
reduce $role_count = count($r) groupby $m, $rel;
sort $role_count desc;
limit 3;
fetch {
  "movie_title": $m.title,
  "role_count": $role_count
};

match
$m isa movie, has released $r;
$r < 1980;
$rel isa acted_in (actor: $p, film: $m), has roles $role;
reduce $count = count groupby $role;
sort $count desc;
limit 10;
fetch {
  "role": $role,
  "role_count": $count
};

match
$p isa person, has name "Keanu Reeves";
$m isa movie, has title "The Matrix";
$rel isa acted_in (actor: $p, film: $m);
fetch {
  "actor": $p.name,
  "movie": $m.title,
  "roles": [ $rel.roles ]
};

match
$m isa movie, has title $t, has released $r;
$r >= 2000;
$r < 2010;
$rev isa reviewed (reviewer: $p, film: $m), has rating $rat;
$rat < 60;
fetch {
  "title": $t
};

match
$m isa movie, has title $t;
$p isa person;
$r isa acted_in (actor: $p, film: $m);
$r has roles $role;
reduce $count = count($role) groupby $r, $m, $t;
match $count == 5;
fetch { "title": $t };

match
$p isa person;
produced (producer: $p, film: $m1);
acted_in (actor: $p, film: $m2);
not { $m1 is $m2; };
fetch { "name": $p.name };

match
$p isa person, has name "Laurence Fishburne";
$rel isa acted_in (actor: $p, film: $m);
$rel has roles $role;
select $role;
distinct;
fetch { "role": $role };
